// Mesma lista/ids do array OBRAS em prototipo/index.html -- mesmo motivo
// dos outros 2 fluxos de Suprimentos/OC: essa API exige `obra_id` (ou
// `rmi_id`) por chamada, sem endpoint "lista todas as obras". CNPEM -
// Auditório (id 103) fica DE FORA de propósito, mesma decisão já tomada
// nos outros fluxos. Se uma obra nova entrar no painel, adicionar aqui
// também.
const OBRAS = [
  { id: 106, nome: 'CNPEM - Faseado' },
  { id: 110, nome: 'Hitachi' },
  { id: 94,  nome: 'Porto Itapoá' },
  { id: 107, nome: 'Novo Nordisk - AP' },
  { id: 108, nome: 'Novo Nordisk - AP - Reforço' },
  { id: 91,  nome: 'Novo Nordisk - UB/SP' },
];

return OBRAS.map(o => ({ json: { id_obra: o.id, nome_obra: o.nome } }));

// Versão SIMPLIFICADA (pedido explícito, 2026-08-20: "é possível retirar
// esta etapa?" -- resposta: não por inteiro sem perder a coluna
// individual, mas dá pra tirar a tradução campo-a-campo e guardar cru).
// Mesmo padrão já usado em `orcamentos_complementares_obra` neste mesmo
// projeto: sem coluna por campo, só `id`/`id_obra` (pro upsert e pro
// filtro por obra, que toda tabela daqui usa) + o item inteiro em `raw`.
// Front-end filtra por `prazo_status`/`desvio_saldo_orcamentario` via
// `raw->>campo` no PostgREST -- ver README, seção "Consumo no painel".
//
// Roda 1x por obra (dentro do loop "Loop obras"). `$('Loop obras (1 por
// vez)').item.json` pega o item ORIGINAL desta volta do loop (id_obra) --
// o `$json` daqui já é a resposta HTTP (o node de HTTP substitui o item
// pelo corpo da resposta).
const idObra = $('Loop obras (1 por vez)').item.json.id_obra;
const corpo = $json;
const itens = Array.isArray(corpo?.data) ? corpo.data : [];

// Guard de paginação mantido -- é o único ponto desta etapa que não é
// "tradução de campo", é uma checagem de integridade: essa API CONFIRMA
// um campo `total` no envelope da resposta, e com `all=true` o esperado é
// vir tudo numa resposta só. Se não bater, `all=true` não desligou a
// paginação como esperado -- melhor travar aqui do que gravar só uma
// fatia dos itens sem avisar.
if (typeof corpo?.total === 'number' && corpo.total !== itens.length) {
  throw new Error(`Obra ${idObra}: API reportou total=${corpo.total} mas 'data' trouxe ${itens.length} itens -- all=true não trouxe tudo de uma vez, precisa de paginação manual (page=1,2,3...) pra essa obra.`);
}

const linhas = itens.map(it => ({
  id: it.id,
  id_obra: idObra,
  raw: it,
  atualizado_em: new Date().toISOString(),
}));

return [{ json: { id_obra: idObra, linhas } }];
